from urllib.parse import quote, urlencode


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def build_request(spec, args):
    known = {p["name"] for p in spec["parameters"]}
    unknown = [name for name in args if name not in known]
    if unknown:
        raise ValueError(f"unknown parameter: {unknown[0]}")

    path = spec["path"]
    query = []
    headers = {}
    for p in spec["parameters"]:
        name = p["name"]
        value = args.get(name)
        if value is None:
            if p.get("required"):
                raise ValueError(f"missing required parameter: {name}")
            continue
        where = p["in"]
        if where == "path":
            path = path.replace("{" + name + "}", quote(_text(value), safe=""))
        elif where == "query":
            if isinstance(value, (list, tuple)):
                query.extend((name, _text(v)) for v in value)
            else:
                query.append((name, _text(value)))
        elif where == "header":
            headers[name] = _text(value)
    target = path + ("?" + urlencode(query) if query else "")
    return (spec["method"], target, headers)

