SPEC = {
    "method": "GET",
    "path": "/libraries/{library}/books/{id}",
    "parameters": [
        {"name": "library", "in": "path", "required": True},
        {"name": "id", "in": "path", "required": True},
        {"name": "fields", "in": "query", "required": False},
        {"name": "include_deleted", "in": "query", "required": False},
        {"name": "Api-Version", "in": "header", "required": True},
    ],
}

@test("a simple request")
def _():
    check_eq(build_request(SPEC, {"library": "main", "id": 42, "Api-Version": "2026-10-01"}),
             ("GET", "/libraries/main/books/42", {"Api-Version": "2026-10-01"}))

@test("escaping path values")
def _():
    method, target, _h = build_request(SPEC, {"library": "a/b c", "id": "x?y", "Api-Version": "1"})
    check_eq(target, "/libraries/a%2Fb%20c/books/x%3Fy")

@test("query parameters in spec order")
def _():
    args = {"include_deleted": True, "fields": ["title", "year"], "id": 1, "library": "l", "Api-Version": "1"}
    check_eq(build_request(SPEC, args)[1], "/libraries/l/books/1?fields=title&fields=year&include_deleted=true")
    args = {"fields": "a b&c", "id": 1, "library": "l", "Api-Version": "1", "include_deleted": None}
    check_eq(build_request(SPEC, args)[1], "/libraries/l/books/1?fields=a+b%26c")
    args = {"include_deleted": False, "id": 1, "library": "l", "Api-Version": 2}
    check_eq(build_request(SPEC, args), ("GET", "/libraries/l/books/1?include_deleted=false", {"Api-Version": "2"}))

@test("missing and unknown parameters")
def _():
    check_raises(ValueError, build_request, SPEC, {"library": "l", "Api-Version": "1"})
    check_raises(ValueError, build_request, SPEC, {"library": "l", "id": 1})
    check_raises(ValueError, build_request, SPEC, {"library": "l", "id": None, "Api-Version": "1"})
    check_raises(ValueError, build_request, SPEC, {"library": "l", "id": 1, "Api-Version": "1", "limit": 5})

@test("another endpoint")
def _():
    spec = {"method": "POST", "path": "/books", "parameters": [{"name": "notify", "in": "query", "required": False}]}
    check_eq(build_request(spec, {}), ("POST", "/books", {}))
    check_eq(build_request(spec, {"notify": True}), ("POST", "/books?notify=true", {}))

